Arguments: {"title":"Find job-related links on homepage","cwd":null,"code":"const tabId = 730410078;
const links = await browserjs(tabId, () => {
  return Array.from(document.querySelectorAll('a')).map(a => ({
    text: a.textContent.trim().replace(/\s+/g, ' '),
    href: a.href
  })).filter(a => a.text.toLowerCase().includes('job') || a.href.toLowerCase().includes('job'));
});
console.log(links);
"}
