<script type="text/javascript">
(function( $ ) {
    $( document ).ready(function() {
        var $mainContainer = $( '#js-odx-content__body' ),
            $headings = $mainContainer.find( 'h2' ),
            $bodyOfContent = $( '#js-odx-content__body' ),
            $containerExpandCollapse = $( '#js-content-expand-collapse' );
        for (var i = 0, length = $headings.length; i < length; i++) {
            var $currentHeading = $( $headings[i] );
            var wrapperDiv = $currentHeading.parent( 'div' );
            if ( wrapperDiv.length && $mainContainer != wrapperDiv ) {
                $currentHeading.unwrap();
            }
        }
        function selectDisplayFormat( unprocessedAuthorSelectedDisplayFormat ) {
            var authorSelectedDisplayFormat = "asTyped";
            switch ( unprocessedAuthorSelectedDisplayFormat ) {
                case '':
                    authorSelectedDisplayFormat = "asTyped";
                    break;
                case 'As Typed':
                    authorSelectedDisplayFormat = "asTyped";
                    break;
                case 'Table of Contents':
                    authorSelectedDisplayFormat = "toc";
                    break;
                case 'Collapsible Sections':
                    authorSelectedDisplayFormat = "twisties";
                    break;
                case 'Horizontal Tabs':
                    authorSelectedDisplayFormat = "horizontalTabs";
                    break;
                case 'Vertical Tabs':
                    authorSelectedDisplayFormat = "verticalTabs";
                    break;
                case 'Horizontal Tabs with Collapsible Sections':
                    authorSelectedDisplayFormat = "horizontalTabsWithCollapsibleSections";
                    break;
            }
            return authorSelectedDisplayFormat;
        }
        var authorSelectedDisplayFormat = selectDisplayFormat( '' ),
            innerCollapsibleSections = selectDisplayFormat( '' );
        var story_transformContent_options = {
            type            : authorSelectedDisplayFormat,
            title           : "Contents",
            initialState    : "closed"
        };
        if ( innerCollapsibleSections !== "asTyped" ) {
            story_transformContent_options["sectionClass"] = 'firstLevelSection';
            story_transformContent_options["haveSubSections"] = true;
            story_transformContent_options["sectionClass"] = 'firstsection';
            story_transformContent_options["headerClass"] = 'firstsectionHeader';
            story_transformContent_options["bodyClass"] = 'firstsectionBody';
            story_transformContent_options["subSectionsOptions"] = {
                sectionClass    : "secondLevelSection",
                headerSelector  : "h3",
                type            : innerCollapsibleSections,
                initialState    : "closed"
            }
        }
        var transformQuery = "#js-odx-content__body";
        if ( authorSelectedDisplayFormat !== "asTyped" || innerCollapsibleSections !== "asTyped" ) {
            $bodyOfContent.story_transformContent( story_transformContent_options );
            var $tableOfContentsContainer = $( '.js-structured-story-body .tableOfContents' );
            if ( typeof $tableOfContentsContainer === 'object' && $tableOfContentsContainer.length === 0) {
                $bodyOfContent.find( 'h2' ).first().addClass( 'firstHeader' );
            }
            if (authorSelectedDisplayFormat === 'twisties') {
                $bodyOfContent.find( 'div.sectionHeader' ).first().trigger('click');
                if ( innerCollapsibleSections === 'twisties' ) {
                    $bodyOfContent.find( 'div.firstsectionHeader' ).first().trigger( 'click' );
                }
                $bodyOfContent.find( '.twisty' ).first().before( $containerExpandCollapse );
                $containerExpandCollapse.removeClass( 'hidden' );
            } else if ( innerCollapsibleSections === "twisties" ) {
                $bodyOfContent.find( '.firstsection' ).first().before( $containerExpandCollapse );
                $containerExpandCollapse.removeClass( 'hidden' );
            }
        }
        $( '.section.twisty, .firstsection.twisty, .secondLevelSection.twisty' ).on('keypress', function( event ){
            var key = event.which || event.keyCode;
            if ( key === 32 ) {
                var child = jQuery( this ).children()[0];
                child.click();
                event.preventDefault();
            }
        });
        var customH2Style = '';
        $bodyOfContent.find( 'h2' ).addClass( customH2Style );

        if( $('.firstsection.story').hasClass( 'twisty' ) ) {
            $( '.firstsection > .firstsectionBody > .secondLevelSection' ).addClass( 'nested' );
        };
    });
})( jQuery );
</script>
