function RefreshFilter(FlatDictionary, ListFilters) {
    $('.divFacet').hide();

    $.each(FlatDictionary, function (key, value) {
        if (value !== 0) {
            $("." + key).show();
            $("." + key + "Count").text(parseInt(value).toLocaleString());
        }
    });

    $.each(ListFilters, function (key, value) {
        let find = "." + key + " > ul";
        $(find).empty();
        $(find).append(value);
    });
}
